import {AudioEngine} from './engine.js';
import {createVideoPipeline} from './video-pipeline.js';
import {videoAudioFXPolicy} from './video-audio-fx-state.js';
const $=s=>document.querySelector(s),assert=(v,m)=>{if(!v)throw new Error(m);},raf=()=>new Promise(resolve=>requestAnimationFrame(resolve));
const W=96,H=64,read=canvas=>{const c=document.createElement('canvas');c.width=W;c.height=H;const ctx=c.getContext('2d');ctx.drawImage(canvas,0,0,W,H);return ctx.getImageData(0,0,W,H);};
const px=(image,x=22,y=32)=>[...image.data.slice((y*W+x)*4,(y*W+x)*4+4)],difference=(a,b)=>{let n=0;for(let i=0;i<a.data.length;i++)n+=Math.abs(a.data[i]-b.data[i]);return n/a.data.length;},equal=(a,b)=>difference(a,b)===0;
const spec=(name='Echo',extra={})=>({name,on:true,depth:80,beat:'1/2',params:{Feedback:70},...extra});
async function until(readValue,predicate,{pump=()=>{},timeout=10000}={}){const end=performance.now()+timeout;let value;do{pump();value=readValue();if(predicate(value))return value;await raf();}while(performance.now()<end);throw new Error('Actual-state predicate timed out: '+JSON.stringify(value));}
function paint(canvas,kind='marker',colour=[230,30,10]){const c=canvas.getContext('2d');c.clearRect(0,0,W,H);if(kind==='transparent'){c.fillStyle=`rgb(${colour})`;c.fillRect(10,10,8,44);return;}c.fillStyle='#000';c.fillRect(0,0,W,H);if(kind==='black')return;if(kind==='ramp'){for(let x=0;x<W;x++){const g=Math.round(255*x/(W-1));c.fillStyle=`rgb(${g},${g},${g})`;c.fillRect(x,0,1,H);}return;}c.fillStyle=`rgb(${colour})`;c.fillRect(10,10,8,44);c.fillStyle='#667799';c.fillRect(60,5,15,12);}
export async function runVideoAudioFXChecks(){
  const checks=[],messages=[],started=performance.now(),engine=new AudioEngine();engine.init();engine.analyser.disconnect();const resume=engine.ctx.resume();
  const left=$('#left'),right=$('#right'),output=$('#output'),state={decks:[0,1].map(index=>({index,track:null,position:0,rate:1,playing:false,videoLoadGeneration:0}))};
  let pipeline,frameId=0;const assets=['left-original','right-original'];const report={startedAt:new Date().toISOString(),policy:videoAudioFXPolicy,checks,messages,
    scope:'Actual AudioEngine/worklet configuration and live signals, original synthetic source canvases, actual WebGL2 pipeline pixels. No native/reference/codec/menu/31-definition acceptance.',
    seams:['Deterministic delay/tail cases supply explicit render timestamps and omit transport clocks; active link descriptors always come from actual engine.configureFX/videoFXLinks.','Actual transport lifecycle cases explicitly use engine.ctx.currentTime and engine.position on a real BufferSource deck.','No fake engine/pipeline/renderer, no external media or audible speaker route.']};
  const settings={transition:'Crossfade',audioFXLink:true,fx:{left:[],right:[],master:[]},overlays:{left:[],right:[],master:[]}};
  async function check(name,run){const evidence={};try{const returned=await run(evidence);checks.push({name,passed:true,evidence:returned??evidence});}catch(error){checks.push({name,passed:false,evidence,error:error.message,stack:error.stack,links:engine.videoFXLinks(),diagnostics:pipeline?.diagnostics()});}$('#status').textContent=`${checks.filter(c=>c.passed).length}/${checks.length} passed · ${name}`;$('#results').textContent=JSON.stringify(report,null,2);await raf();}
  const configure=(banks=[[spec()]],routes=['Deck 1'],bpms=[120,120,120,120])=>{engine.configureFX(banks,routes,bpms);return engine.videoFXLinks();};
  function render(time,extra={}){const context={time,frameId:++frameId,amount:0,upfaders:[1,1],channels:assets.map(assetId=>({assetId,bpm:120,rate:1,audioAvailable:false})),master:{bpm:120,audioAvailable:false},masterAssetId:assets.join('|'),audioFXLinks:engine.videoFXLinks(),...extra};const result=pipeline.render([left,right],settings,context);output.getContext('2d').clearRect(0,0,W,H);output.getContext('2d').drawImage(result.output,0,0);return {channels:result.channels.map(read),output:read(result.output),diagnostics:pipeline.diagnostics(),context};}
  const target=result=>result.diagnostics.audioFXLinks.targets;
  async function audio(frequency=0){const old=state.decks[0];engine.pause(old);const duration=8,buffer=engine.ctx.createBuffer(1,engine.ctx.sampleRate*duration,engine.ctx.sampleRate),data=buffer.getChannelData(0);if(frequency)for(let i=0;i<data.length;i++)data[i]=.15*Math.sin(2*Math.PI*frequency*i/engine.ctx.sampleRate);const deck={index:0,track:{id:'semantic-pcm-'+frequency,duration,bpm:120},position:0,rate:1,playing:false,processing:false,keylock:false,keyShift:0,reverse:false,loop:true,loopIn:0,loopOut:duration,stems:[true,true,true,true],stemFX:[false,false,false,false],videoLoadGeneration:(old.videoLoadGeneration||0)+1};state.decks[0]=deck;engine.buffers.set(deck.track.id,buffer);await engine.start(deck);return deck;}
  function transport(){const d=state.decks[0];return {playing:d.playing,generation:d.videoLoadGeneration,sources:[{id:d.track?.id,playing:d.playing,position:engine.position(d),rate:d.rate*(d.reverse?-1:1),generation:d.videoLoadGeneration}]};}
  function realRender(){return render(engine.ctx.currentTime,{channels:[{assetId:assets[0],audioTransport:transport()},{assetId:assets[1]}],master:{audioTransport:transport()}});}
  function reset(){pipeline.reset();settings.audioFXLink=true;settings.fx={left:[],right:[],master:[]};paint(left);paint(right,'marker',[20,210,80]);}
  try{
    await check('Actual AudioEngine prepares real DJ-FX graph with a playing silent PCM source',async()=>{await resume;await engine.resume();pipeline=createVideoPipeline({width:W,height:H});paint(left);paint(right,'marker',[20,210,80]);await audio(0);configure();await until(()=>({time:engine.ctx.currentTime,signal:engine.videoAnalysis(0)}),v=>v.time>.08&&v.signal.audioAvailable&&v.signal.level<1e-6);return {state:engine.ctx.state,effectsPrepared:engine.effectsPrepared,playing:state.decks[0].playing,level:engine.videoAnalysis(0).level,links:engine.videoFXLinks()};});
    await check('Link OFF is exact pixel bypass despite assigned enabled audio Echo',()=>{reset();configure();settings.audioFXLink=false;const r=render(0);assert(equal(r.channels[0],read(left))&&equal(r.channels[1],read(right)),'Link OFF altered input pixels.');assert(target(r).left.active.length===0,'Link OFF allocated active treatment.');return {leftDifference:difference(r.channels[0],read(left)),backend:target(r).left.backend};});
    await check('Static source plus actual silent audio Echo produces a delayed real-frame ghost only on its assigned channel',()=>{reset();configure();const first=render(0),r=render(.25);assert(engine.videoAnalysis(0).level<1e-6,'PCM silence prerequisite unavailable.');assert(px(first.channels[0])[0]===0&&px(r.channels[0])[0]>50,'At1T a retained red marker must appear outside its original bounds.');assert(equal(r.channels[1],read(right)),'Left Echo changed the right channel.');assert(target(r).left.active.length===1&&target(r).master.active.length===0,'Deck route was duplicated into master.');return {before:px(first.channels[0]),atDelay:px(r.channels[0]),rightDifference:difference(r.channels[1],read(right)),links:target(r)};});
    await check('Bass audio with semantic FX disabled does not fabricate an Echo/Distortion link',async()=>{reset();configure([[spec('Echo',{on:false})]]);await audio(93.75);await until(()=>engine.videoAnalysis(0),v=>v.bass>.02&&v.level>.02);const r=render(0);assert(equal(r.channels[0],read(left)),'Bass-only signal changed pixels with semantic FX disabled.');assert(target(r).left.active.length===0,'FFT was mistaken for an enabled DJ-FX identity.');return {audio:engine.videoAnalysis(0),difference:difference(r.channels[0],read(left))};});
    await check('Unsupported audio names/assignments remain explicit and never substitute a mapped effect',()=>{reset();configure([[spec('Delay')],[spec('Echo')]],['Deck 1','Sampler']);const r=render(0),d=r.diagnostics.audioFXLinks;assert(d.unsupported.length===2,'Unsupported controls were not diagnosed.');assert(target(r).left.active.length===0&&equal(r.channels[0],read(left)),'Unsupported audio effect received a silent substitute.');return d.unsupported;});
    await check('Actual audio Distortion identity changes static pixels without FFT or generated motion',()=>{reset();paint(left,'ramp');configure([[spec('Distortion',{depth:100,params:{Drive:80,Character:60,Type:'Smooth Drive',Tone:0}})]]);const r=render(0);assert(difference(r.channels[0],read(left))>5,'Enabled Distortion lacked actual pixel response.');assert(equal(r.channels[1],read(right)),'Left Distortion leaked to right.');return {difference:difference(r.channels[0],read(left)),sample:px(r.channels[0],24),link:target(r).left.active};});
    await check('Deck2 assignment affects only right pixels and no left/master duplicate',()=>{reset();paint(right,'ramp');configure([[spec('Distortion',{depth:100,params:{Drive:90}})]],['Deck 2']);const r=render(0,{amount:1});assert(equal(r.channels[0],read(left))&&difference(r.channels[1],read(right))>5,'Right assignment did not isolate pixels.');assert(target(r).master.active.length===0,'Right bank duplicated into master.');return {leftDifference:difference(r.channels[0],read(left)),rightDifference:difference(r.channels[1],read(right)),targets:target(r)};});
    await check('Master assignment changes final pixels while both channel previews stay untouched',()=>{reset();paint(left,'ramp');configure([[spec('Distortion',{depth:100,params:{Drive:80}})]],['Master']);const r=render(0);assert(equal(r.channels[0],read(left))&&equal(r.channels[1],read(right)),'Master treatment altered channel previews.');assert(difference(r.output,read(left))>5,'Master treatment did not alter final output.');assert(target(r).master.active.length===1&&target(r).left.active.length===0,'Master route applied more than once.');return {masterDifference:difference(r.output,read(left)),targets:target(r)};});
    await check('Two explicitly master-assigned banks execute in order exactly once each',()=>{reset();configure([[spec('Echo')],[spec('Distortion',{depth:60})]],['Master','Master']);render(0);const r=render(.25);assert(JSON.stringify(target(r).master.active.map(l=>l.id))==='["0:0","1:0"]','Master sharing duplicated/reordered bank links.');assert(target(r).left.active.length===0&&target(r).right.active.length===0,'Master bank was also applied to channels.');return {master:target(r).master.active};});
    await check('Depth changes real static colour strength with geometry suppressed',()=>{reset();paint(left,'ramp');const baseline=read(left);configure([[spec('Distortion',{depth:25,params:{Drive:80}})]]);const low=render(0,{reducedMotion:true});configure([[spec('Distortion',{depth:90,params:{Drive:80}})]]);const high=render(.01,{reducedMotion:true});const a=difference(low.channels[0],baseline),b=difference(high.channels[0],baseline);assert(a>1&&b>a*2,'Greater depth did not increase declared static transform strength.');return {low:a,high:b};});
    await check('Hard Clip and Foldback follow distinct numeric RGB contracts at a known ramp pixel',()=>{reset();paint(left,'ramp');configure([[spec('Distortion',{depth:100,params:{Drive:100,Type:'Hard Clip'}})]]);const hard=render(0,{reducedMotion:true});configure([[spec('Distortion',{depth:100,params:{Drive:100,Type:'Foldback'}})]]);const folded=render(.01,{reducedMotion:true});assert(px(hard.channels[0],24)[0]<3&&px(folded.channels[0],24)[0]>150,'Declared clipping/foldback transfer did not affect the known pixel.');return {input:px(read(left),24),hardClip:px(hard.channels[0],24),foldback:px(folded.channels[0],24)};});
    await check('Echo actual BPM/beat/BeatModify changes the timestamp at which the first marker returns',evidence=>{const samples=evidence.samples=[];for(const [bpm,beat,modifier,T] of [[120,'1',1,.5],[240,'1',1,.25],[240,'1','2 dotted',.75]]){reset();configure([[spec('Echo',{depth:100,beat,params:{Feedback:0,'Beat Modify':modifier}})]],['Deck 1'],[bpm]);render(0);paint(left,'black');const early=render(T-.001),due=render(T);samples.push({bpm,beat,modifier,T,early:px(early.channels[0]),due:px(due.channels[0]),semanticDelay:target(due).left.active[0].delaySeconds,earlyState:target(early).left.active,dueState:target(due).left.active});assert(px(early.channels[0])[0]===0&&px(due.channels[0])[0]>80,'Echo timestamp did not follow actual configured beat timing.');}return samples;});
    await check('Feedback controls finite later-tap weight without recursive unbounded video output',()=>{const samples=[];for(const feedback of [0,80]){reset();configure([[spec('Echo',{depth:100,beat:'1/4',params:{Feedback:feedback}})]]);render(0);paint(left,'black');const r=render(.25);samples.push({feedback,pixel:px(r.channels[0],28),active:target(r).left.active});}assert(samples[0].pixel[0]===0&&samples[1].pixel[0]>20,'Second shifted repeat did not respond to feedback decay.');return samples;});
    await check('Disabled link clears its tail immediately and re-enable cannot resurrect old frames',()=>{reset();configure();render(0);paint(left,'black');const wet=render(.25);assert(px(wet.channels[0])[0]>50,'Echo prerequisite lacked marker.');configure([[spec('Echo',{on:false})]]);const off=render(.26);assert(equal(off.channels[0],read(left)),'Disabled Echo retained its tail.');configure();const resumed=render(.27);assert(equal(resumed.channels[0],read(left)),'Re-enabled Echo resurrected old red history.');return {wet:px(wet.channels[0]),off:px(off.channels[0]),reenabled:px(resumed.channels[0])};});
    await check('Reassignment releases old target history rather than leaking it into the new target',()=>{reset();configure();render(0);paint(left,'black');render(.25);configure([[spec()]],['Deck 2']);const r=render(.26);assert(equal(r.channels[0],read(left))&&equal(r.channels[1],read(right)),'Reassignment reused prior-target Echo history.');assert(target(r).left.active.length===0&&target(r).right.active[0].taps.every(i=>i===-1),'Reassigned link did not start with empty target history.');return target(r);});
    await check('Source generation replacement clears previously captured colour even on the same canvas',()=>{reset();configure();render(0);paint(left,'black');assets[0]='new-source-generation';const r=render(.25);assert(equal(r.channels[0],read(left)),'New source inherited previous red Echo.');assert(target(r).left.active[0].resetReasons.includes('source-asset'),'Source generation reset was not observed.');return target(r).left.active;});
    await check('Backward render time and duplicate frame IDs obey declared capture lifecycle',()=>{reset();configure();render(0);const wet=render(.25),captured=target(wet).left.active[0].captureCount;const duplicate=render(.25,{frameId:wet.context.frameId});assert(target(duplicate).left.active[0].captureCount===captured,'Duplicate input frame captured twice.');paint(left,'black');const backward=render(.1);assert(equal(backward.channels[0],read(left)),'Backward clock reused future Echo frame.');assert(target(backward).left.active[0].resetReasons.includes('backward-clock'),'Backward clock reset not diagnosed.');return {captured,duplicate:target(duplicate).left.active,backward:target(backward).left.active};});
    await check('Removing preceding Distortion clears downstream Echo history containing the old topology',()=>{reset();configure([[spec('Distortion',{depth:100}),spec('Echo',{depth:100,beat:'1/4'})]]);render(0);paint(left,'black');render(.125);configure([[spec('Distortion',{on:false}),spec('Echo',{depth:100,beat:'1/4'})]]);const r=render(.25);assert(equal(r.channels[0],read(left)),'Downstream Echo retained a removed upstream treatment.');assert(target(r).left.active[0].resetReasons.includes('upstream-topology'),'Topology reset did not reach downstream history.');return target(r).left.active;});
    await check('Actual AudioEngine pause/seek/reverse/reload clocks reset temporal link history',async()=>{reset();await audio(440);configure([[spec('Echo',{depth:100,beat:'1/32'})]]);const deck=state.decks[0];realRender();paint(left,'black');await until(()=>{const r=realRender();return{pixel:px(r.channels[0]),active:target(r).left.active};},v=>v.pixel[0]>50);engine.pause(deck);let r=realRender();assert(equal(r.channels[0],read(left))&&target(r).left.active[0].suppressed,'Actual pause did not clear/suppress Echo.');await engine.start(deck);realRender();await engine.seek(deck,3);r=realRender();assert(target(r).left.active[0].resetReasons.includes('transport-seek'),'Actual seek was not detected.');await engine.setReverse(deck,true);r=realRender();assert(target(r).left.active[0].resetReasons.includes('transport-direction'),'Actual reverse direction did not reset.');deck.videoLoadGeneration++;r=realRender();assert(target(r).left.active[0].resetReasons.includes('transport-generation'),'Reload generation did not reset.');await engine.setReverse(deck,false);return {position:engine.position(deck),playing:deck.playing,final:target(r).left.active};});
    await check('Reduced Motion removes Echo trails and warp while retaining static semantic colour',()=>{reset();configure();render(0);const normal=render(.25);assert(px(normal.channels[0])[0]>50,'Echo prerequisite absent.');const reduced=render(.26,{reducedMotion:true});assert(equal(reduced.channels[0],read(left))&&target(reduced).left.active[0].suppressed,'Reduced Motion retained automatic trails.');paint(left,'ramp');configure([[spec('Distortion',{depth:100,params:{Drive:80,Type:'Hard Clip'}})]]);const a=render(.3,{reducedMotion:true}),b=render(4,{reducedMotion:true});assert(equal(a.channels[0],b.channels[0])&&difference(a.channels[0],read(left))>5,'Reduced-motion colour was animated or removed.');return {echo:px(reduced.channels[0]),colourDifference:difference(a.channels[0],read(left)),stableDifference:difference(a.channels[0],b.channels[0])};});
    await check('Original keyed alpha stays straight red in partially transparent Echo ghosts',evidence=>{reset();paint(left,'transparent',[255,0,0]);configure([[spec('Echo',{depth:100,params:{Feedback:0}})]]);render(0);const r=render(.25),p=px(r.channels[0]);Object.assign(evidence,{ghost:p,input:px(read(left),14),sourceOutside:px(read(left)),active:target(r).left.active});assert(p[0]===255&&p[1]===0&&p[2]===0&&p[3]>50&&p[3]<240,'Echo alpha was opaque, absent or dark-fringed: '+p);return {ghost:p};});
    await check('Link OFF restores both ordinary configured Video slots without mutating their parameters',()=>{reset();paint(left,'ramp');settings.fx.left=[{name:'Negative',on:true,value:1,params:{}},{name:'Gamma',on:true,value:1,params:{gamma:1.7}}];const before=JSON.stringify(settings.fx);configure([[spec('Distortion',{depth:100})]]);settings.audioFXLink=false;const dry=render(0);settings.audioFXLink=true;const linked=render(.01);settings.audioFXLink=false;const restored=render(.02);assert(difference(linked.channels[0],dry.channels[0])>1,'Linked path did not feed ordinary slots.');assert(equal(restored.channels[0],dry.channels[0]),'Link OFF failed to restore independently configured normal slots.');assert(JSON.stringify(settings.fx)===before,'Semantic link mutated normal slot settings.');return {linkedDifference:difference(linked.channels[0],dry.channels[0]),restoredDifference:difference(restored.channels[0],dry.channels[0]),ordinarySlots:settings.fx.left};});
    await check('Bridge enable changes video pixels but not measured actual post-master audio amplitude',async evidence=>{reset();await audio(440);configure([[spec('Distortion',{depth:60,params:{Drive:60}})]]);paint(left,'ramp');const signature=JSON.stringify(engine.fxState),aperture=2048/engine.ctx.sampleRate;evidence.stationarityWindows=[];evidence.measurements=[];
      async function collect(enabled,count=16){settings.audioFXLink=enabled;const values=[];evidence.latestAudioWindow={enabled,samples:values};let lastTime=-Infinity;await until(()=>{realRender();const time=engine.ctx.currentTime;if(time-lastTime>=aperture){lastTime=time;values.push({time,level:engine.videoAnalysis(4).level});}return values;},v=>v.length>=count);return values;}
      const mean=values=>values.reduce((a,b)=>a+b.level,0)/values.length;
      // Establish stationarity BEFORE taking the baseline. After any toggle the
      // fixed, equal sample apertures do not wait for a preferred audio result.
      let stable=false;for(let attempt=0;attempt<10&&!stable;attempt++){const samples=await collect(false),a=mean(samples.slice(0,8)),b=mean(samples.slice(8)),range=Math.max(...samples.map(v=>v.level))-Math.min(...samples.map(v=>v.level));stable=a>.001&&Math.abs(a-b)<.0005&&range<.004;evidence.stationarityWindows.push({samples,firstHalf:a,secondHalf:b,range,stable});}assert(stable,'Held audio never reached the declared pre-toggle stationarity prerequisite.');
      const levels=[];for(const enabled of [false,true,false]){const samples=await collect(enabled),level=mean(samples);evidence.measurements.push({enabled,samples,mean:level});levels.push(level);}const [off,on,again]=levels;Object.assign(evidence,{off,on,again,tolerance:.002,apertureSeconds:aperture,scope:'Real post-master time-domain RMS under held audio FX/PCM after measured pre-toggle stationarity; equal fixed post-toggle windows, not sample-for-sample or vendor sonic equivalence.'});assert(Math.max(Math.abs(off-on),Math.abs(off-again))<.002,'Bridge toggle materially changed held audio graph amplitude: '+JSON.stringify({off,on,again}));assert(JSON.stringify(engine.fxState)===signature,'Bridge changed configured audio FX state.');return evidence;});
    await check('Explicit reset and disposal release all link state and reject subsequent rendering',()=>{pipeline.reset();const r=render(engine.ctx.currentTime);assert(Object.values(target(r)).every(t=>t.active.every(l=>l.taps.every(i=>i===-1))),'Reset reused a past Echo frame.');pipeline.dispose();let rejected=false;try{pipeline.render([left,right]);}catch{rejected=true;}assert(rejected,'Disposed pipeline rendered again.');return {rejected};});
  }catch(error){checks.push({name:'Harness setup/unhandled failure',passed:false,error:error.message,stack:error.stack});}
  finally{try{pipeline?.dispose();engine.videoAnalyzers?.dispose();engine.silence();await engine.ctx.close();}catch(error){messages.push('Cleanup: '+error.message);}}
  report.passed=checks.filter(c=>c.passed).length;report.failed=checks.filter(c=>!c.passed).length;report.durationMs=performance.now()-started;window.videoAudioFXHarnessResult=report;$('#results').textContent=JSON.stringify(report,null,2);$('#status').textContent=`${report.passed} passed / ${report.failed} failed`;return report;
}
$('#run').onclick=async()=>{$('#run').disabled=true;$('#status').textContent='Running actual semantic-link GPU/audio evidence…';try{await runVideoAudioFXChecks();}catch(error){window.videoAudioFXHarnessResult={passed:0,failed:1,fatal:error.message};$('#results').textContent=error.stack;$('#status').textContent='Fatal harness failure';}finally{$('#run').disabled=false;}};
